async function B(l){const h=new(window.AudioContext||window.webkitAudioContext);try{const s=await(await fetch(l)).arrayBuffer(),r=await h.decodeAudioData(s),d=r.sampleRate,c=r.getChannelData(0),A=r.duration,g=Math.round(d*.02),p=Math.round(d*.01),M=[];for(let t=0;t+g<=c.length;t+=p){let i=0;for(let n=t;n<t+g;n++)i+=c[n]*c[n];M.push(Math.sqrt(i/g))}const a=b(M,5),x=Math.round(.4/.01),o=[];for(let t=1;t<a.length-1;t++){const i=Math.max(0,t-x),n=Math.min(a.length,t+x);let u=0;for(let e=i;e<n;e++)u+=a[e];u/=n-i;const w=u*1.4;if(a[t]>w&&a[t]>a[t-1]&&a[t]>=a[t+1]){const e=t*p/d;(o.length===0||e-o[o.length-1]>=.25)&&o.push(parseFloat(e.toFixed(3)))}}let y=0,F=0;if(o.length>=4){const t=[];for(let e=1;e<o.length;e++)t.push(o[e]-o[e-1]);t.sort((e,f)=>e-f);const i=t[Math.floor(t.length/2)];y=parseFloat((60/i).toFixed(1));const n=t.reduce((e,f)=>e+f,0)/t.length,u=t.reduce((e,f)=>e+(f-n)**2,0)/t.length,w=Math.sqrt(u)/n;F=parseFloat(Math.max(0,Math.min(1,1-w)).toFixed(2))}return{beats:o,bpm:y,confidence:F}}finally{h.state!=="closed"&&await h.close().catch(()=>{})}}function b(l,h){const m=new Array(l.length);for(let s=0;s<l.length;s++){let r=0,d=0;for(let c=Math.max(0,s-h);c<=Math.min(l.length-1,s+h);c++)r+=l[c],d++;m[s]=r/d}return m}export{B as detectBeats};
